"""
EVERY DOT = 1 MEASUREMENT — a hydrogen atom built from 2,000,000 electron measurements (Blender 4.2+ / 5.x)   @AlexCarten_

Every point is one place the electron was found, sampled exactly from |psi|^2 of hydrogen 4d (n=4, l=2, m=0):
  R(r) ~ r^2 (1 - r/12) e^(-r/4),  Y ~ 3cos^2(theta) - 1   (r in Bohr radii)
Gold = wave positive, blue = wave negative. The dark shell at r = 12 is the radial node: the electron is never there.

File > New > General -> Scripting -> Open -> Run Script -> Ctrl+F12
Video: ~/OrbitalRenders/every_dot/every_dot.mp4  (sound: every_dot_sound.wav, same timing — drop it in CapCut)
No Python runs during playback/render (baked keyframes + geometry nodes).
"""
import bpy, math, os, base64
import numpy as np

ASSETS = {
    'cnt_l.png': '',
    'end.png': '',
    'form.png': '',
    'handle.png': '',
    'hook.png': '',
    'node.png': '',
    'top1.png': '',
    'top2.png': '',
    'top3.png': '',
    'top4.png': '',
    'top5.png': '',
    'poppins_bi.ttf': '',
}

# ---------------- settings ----------------
NP        = 420_000         # number of measurements (points). fewer + bigger = each particle reads clearly
SECONDS   = 31
FPS       = 30
ENGINE    = "EEVEE"
SAMPLES   = 64
RES_SCALE = 100
POINT_PX  = 5.0             # point size on screen (each point is a small lit sphere)
BRIGHT    = 1.0             # glow of the dots on top of the lighting
OUTPUT    = os.path.join(os.path.expanduser("~"), "OrbitalRenders", "every_dot")
NF = SECONDS * FPS
DIST = 160.0; LENS = 46.5; KH = 18.0 / LENS; PXK = KH / 960.0

# ---------------- timeline (same as the MP4) ----------------
T_COLLAPSE = (2.2, 2.75)
T_B0, T_B1, T_B2 = 2.9, 8.2, 15.0           # 1 dot -> 150 dots -> all dots
T_TILT = (15.5, 18.5)
T_CUT = (20.5, 22.5); T_UNCUT = (25.6, 26.6)
T_END = 26.8
GOLD = (1.0, 0.42, 0.02); BLUE = (0.02, 0.22, 1.0)        # saturated

def ease(u):
    u = np.clip(u, 0, 1); return u * u * (3 - 2 * u)
def ef(u): return float(ease(u))
T = np.arange(NF) / FPS
def fade(pairs): return np.interp(T, [p[0] for p in pairs], [p[1] for p in pairs])
def show(a, b, fi=0.5, fo=0.4): return [(0, 0), (max(a, 0.001), 0), (a + fi, 1), (b, 1), (b + fo, 0), (SECONDS, 0)]
def count(t):
    if t < T_B0: return float(NP)
    if t < T_B1: return math.exp(math.log(150) * (t - T_B0) / (T_B1 - T_B0))
    if t < T_B2: return math.exp(math.log(150) + (math.log(NP) - math.log(150)) * ef((t - T_B1) / (T_B2 - T_B1)) ** 1.1)
    return float(NP)

# ---------------- sampling |psi|^2 exactly ----------------
def sample(n):
    rng = np.random.default_rng(1926)
    r = np.linspace(0, 110, 200001); R = r ** 2 * (1 - r / 12.0) * np.exp(-r / 4.0)
    pdf = r ** 2 * R ** 2; cdf = np.cumsum(pdf); cdf /= cdf[-1]
    rr = np.interp(rng.random(n), cdf, r)
    c = np.empty(0)
    while len(c) < n:                                   # angular part (3c^2 - 1)^2 / 4 <= 1
        cand = rng.uniform(-1, 1, 2 * n); keep = rng.random(2 * n) < (3 * cand ** 2 - 1) ** 2 / 4.0
        c = np.concatenate([c, cand[keep]])
    c = c[:n]; s = np.sqrt(1 - c * c); ph = rng.uniform(0, 2 * np.pi, n)
    xyz = np.stack([rr * s * np.cos(ph), rr * s * np.sin(ph), rr * c], 1)
    sgn = np.sign((1 - rr / 12.0) * (3 * c * c - 1))
    return xyz.astype(np.float32), sgn.astype(np.float32)
# ---------------- helpers ----------------
def clear_scene():
    for ob in list(bpy.data.objects): bpy.data.objects.remove(ob, do_unlink=True)
    for coll in (bpy.data.meshes, bpy.data.curves, bpy.data.materials, bpy.data.cameras, bpy.data.lights, bpy.data.actions, bpy.data.images):
        for b in list(coll):
            if b.users == 0: coll.remove(b)
    for ng in list(bpy.data.node_groups):
        if ng.users == 0: bpy.data.node_groups.remove(ng)

def link(ob):
    bpy.context.scene.collection.objects.link(ob); return ob

def fcurves_of(idblock):
    act = idblock.animation_data.action
    if hasattr(act, "fcurves"):
        try:
            if len(act.fcurves): return list(act.fcurves)
        except Exception: pass
    out = []
    for layer in getattr(act, "layers", []):
        for strip in layer.strips:
            for cb in strip.channelbags: out += list(cb.fcurves)
    return out

def bake(idblock, path, index, values, owner=None):
    owner = owner or idblock
    if index is None:
        setattr(idblock, path, type(getattr(idblock, path))(values[0])); idblock.keyframe_insert(path, frame=1)
    else:
        getattr(idblock, path)[index] = values[0]; idblock.keyframe_insert(path, index=index, frame=1)
    want = path if owner is idblock else idblock.path_from_id(path)
    fc = [f for f in fcurves_of(owner) if f.data_path == want and (index is None or f.array_index == index)][0]
    fc.keyframe_points.clear(); fc.keyframe_points.add(len(values))
    co = np.empty(2 * len(values), np.float32); co[0::2] = np.arange(1, len(values) + 1); co[1::2] = values
    fc.keyframe_points.foreach_set("co", co)
    interp = 0 if (index is None and isinstance(getattr(idblock, path), bool)) else 1
    try: fc.keyframe_points.foreach_set("interpolation", np.full(len(values), interp, np.int32))
    except Exception:
        for kp in fc.keyframe_points: kp.interpolation = 'LINEAR'
    fc.update()

def blend(m):
    for attr, val in (("blend_method", 'BLEND'), ("surface_render_method", 'BLENDED')):
        try: setattr(m, attr, val)
        except Exception: pass

def glow_mat(name, rgb, strength, attr=None):
    """additive emission; Value node = fade; optional geometry attribute multiplies the strength"""
    m = bpy.data.materials.new(name); m.use_nodes = True
    N_, Lk = m.node_tree.nodes, m.node_tree.links; N_.clear()
    out = N_.new("ShaderNodeOutputMaterial"); em = N_.new("ShaderNodeEmission"); em.inputs["Color"].default_value = (*rgb, 1)
    val = N_.new("ShaderNodeValue"); val.outputs[0].default_value = 1.0
    mul = N_.new("ShaderNodeMath"); mul.operation = 'MULTIPLY'; mul.inputs[1].default_value = strength
    Lk.new(val.outputs[0], mul.inputs[0]); s = mul.outputs[0]
    if attr:
        at = N_.new("ShaderNodeAttribute"); at.attribute_type = 'GEOMETRY'; at.attribute_name = attr
        m2 = N_.new("ShaderNodeMath"); m2.operation = 'MULTIPLY'; Lk.new(s, m2.inputs[0]); Lk.new(at.outputs["Fac"], m2.inputs[1]); s = m2.outputs[0]
    Lk.new(s, em.inputs["Strength"])
    tr = N_.new("ShaderNodeBsdfTransparent"); add = N_.new("ShaderNodeAddShader")
    Lk.new(tr.outputs[0], add.inputs[0]); Lk.new(em.outputs[0], add.inputs[1]); Lk.new(add.outputs[0], out.inputs[0]); blend(m)
    return m, val

def glass_mat(name, rgb, opacity):
    """see-through tinted glass: transparent mixed with a little emission (works in every EEVEE version)"""
    m = bpy.data.materials.new(name); m.use_nodes = True
    N_, Lk = m.node_tree.nodes, m.node_tree.links; N_.clear()
    out = N_.new("ShaderNodeOutputMaterial"); em = N_.new("ShaderNodeEmission")
    em.inputs["Color"].default_value = (*rgb, 1); em.inputs["Strength"].default_value = 1.0
    val = N_.new("ShaderNodeValue"); val.outputs[0].default_value = 1.0
    mul = N_.new("ShaderNodeMath"); mul.operation = 'MULTIPLY'; mul.inputs[1].default_value = opacity
    Lk.new(val.outputs[0], mul.inputs[0])
    tr = N_.new("ShaderNodeBsdfTransparent"); mx = N_.new("ShaderNodeMixShader")
    Lk.new(mul.outputs[0], mx.inputs[0]); Lk.new(tr.outputs[0], mx.inputs[1]); Lk.new(em.outputs[0], mx.inputs[2])
    Lk.new(mx.outputs[0], out.inputs[0]); blend(m)
    for attr, v in (("surface_render_method", 'DITHERED'), ("blend_method", 'HASHED')):   # no sorting -> the glass never vanishes
        try: setattr(m, attr, v)
        except Exception: pass
    try: m.use_backface_culling = False
    except Exception: pass
    return m, val

def image_mat(name, img):
    m = bpy.data.materials.new(name); m.use_nodes = True
    N_, Lk = m.node_tree.nodes, m.node_tree.links; N_.clear()
    out = N_.new("ShaderNodeOutputMaterial")
    tex = N_.new("ShaderNodeTexImage"); tex.image = img; tex.interpolation = 'Cubic'
    em = N_.new("ShaderNodeEmission"); Lk.new(tex.outputs["Color"], em.inputs["Color"])
    val = N_.new("ShaderNodeValue"); val.outputs[0].default_value = 1.0
    mul = N_.new("ShaderNodeMath"); mul.operation = 'MULTIPLY'
    Lk.new(tex.outputs["Alpha"], mul.inputs[0]); Lk.new(val.outputs[0], mul.inputs[1])
    tr = N_.new("ShaderNodeBsdfTransparent"); mx = N_.new("ShaderNodeMixShader")
    Lk.new(mul.outputs[0], mx.inputs[0]); Lk.new(tr.outputs[0], mx.inputs[1]); Lk.new(em.outputs[0], mx.inputs[2])
    Lk.new(mx.outputs[0], out.inputs[0]); blend(m)
    return m, val

def M_(N_, Lk, op, a, b=None):
    n = N_.new("ShaderNodeMath"); n.operation = op
    for i, v in enumerate((a, b)):
        if v is None: continue
        if isinstance(v, (int, float)): n.inputs[i].default_value = v
        else: Lk.new(v, n.inputs[i])
    return n.outputs[0]

def new_gn(name):
    ng = bpy.data.node_groups.new(name, 'GeometryNodeTree')
    ng.interface.new_socket("Geometry", in_out='INPUT', socket_type='NodeSocketGeometry')
    ng.interface.new_socket("Geometry", in_out='OUTPUT', socket_type='NodeSocketGeometry')
    return ng, ng.nodes, ng.links, ng.nodes.new("NodeGroupInput"), ng.nodes.new("NodeGroupOutput")

def drv(N_, Lk, ob):
    oi = N_.new("GeometryNodeObjectInfo"); oi.inputs["Object"].default_value = ob
    sx = N_.new("ShaderNodeSeparateXYZ"); Lk.new(oi.outputs["Location"], sx.inputs[0]); return sx.outputs

def tube(N_, Lk, curve, radius, mat, res=8):
    circ = N_.new("GeometryNodeCurvePrimitiveCircle"); circ.inputs["Resolution"].default_value = res
    Lk.new(radius, circ.inputs["Radius"])
    c2m = N_.new("GeometryNodeCurveToMesh"); Lk.new(curve, c2m.inputs["Curve"]); Lk.new(circ.outputs["Curve"], c2m.inputs["Profile Curve"])
    sm = N_.new("GeometryNodeSetMaterial"); sm.inputs["Material"].default_value = mat
    Lk.new(c2m.outputs[0], sm.inputs["Geometry"]); return sm.outputs[0]

def lines_obj(name, segs, D, mat, thick=0.55):
    verts, edges = [], []
    for poly in segs:
        i0 = len(verts); verts.extend(poly); edges.extend((i0 + k, i0 + k + 1) for k in range(len(poly) - 1))
    me = bpy.data.meshes.new(name); me.from_pydata(verts, edges, []); me.update()
    ob = link(bpy.data.objects.new(name, me))
    ng, N_, Lk, gi, go = new_gn(name); d = drv(N_, Lk, D)
    m2c = N_.new("GeometryNodeMeshToCurve"); Lk.new(gi.outputs[0], m2c.inputs["Mesh"])
    Lk.new(tube(N_, Lk, m2c.outputs[0], M_(N_, Lk, 'MULTIPLY', d[1], thick), mat, 6), go.inputs[0])
    ob.modifiers.new(name, 'NODES').node_group = ng
    return ob


def counter_group(Dv, axis, font, mat):
    ng, N_, Lk, gi, go = new_gn("Counter%d" % axis)
    d = drv(N_, Lk, Dv)
    fl = M_(N_, Lk, 'FLOOR', M_(N_, Lk, 'ADD', d[axis], 0.5))
    vs = N_.new("FunctionNodeValueToString"); Lk.new(fl, vs.inputs["Value"])
    st = N_.new("GeometryNodeStringToCurves"); st.inputs["Size"].default_value = 70
    Lk.new(vs.outputs[0], st.inputs["String"])
    for v in ("Center", "CENTER"):
        try: st.inputs["Align X"].default_value = v; break
        except Exception:
            try: st.align_x = v; break
            except Exception: pass
    if font is not None:
        try: st.inputs["Font"].default_value = font
        except Exception:
            try: st.font = font
            except Exception: pass
    ri = N_.new("GeometryNodeRealizeInstances"); Lk.new(st.outputs[0], ri.inputs[0])
    fill = N_.new("GeometryNodeFillCurve"); Lk.new(ri.outputs[0], fill.inputs[0])
    sm = N_.new("GeometryNodeSetMaterial"); sm.inputs["Material"].default_value = mat
    Lk.new(fill.outputs[0], sm.inputs["Geometry"]); Lk.new(sm.outputs[0], go.inputs[0])
    return ng


def load_assets():
    d = os.path.join(OUTPUT, "assets"); os.makedirs(d, exist_ok=True); imgs, font = {}, None
    for n, b in ASSETS.items():
        p = os.path.join(d, n)
        with open(p, "wb") as f: f.write(base64.b64decode(b))
        if n.endswith(".ttf"):
            try: font = bpy.data.fonts.load(p, check_existing=True)
            except Exception: font = None
        else:
            im = bpy.data.images.load(p, check_existing=False); im.pack(); imgs[n[:-4]] = im
    return imgs, font


def build_world():
    w = bpy.context.scene.world or bpy.data.worlds.new("World")
    bpy.context.scene.world = w; w.use_nodes = True
    N_, Lk = w.node_tree.nodes, w.node_tree.links
    for n in list(N_): N_.remove(n)
    bg = N_.new("ShaderNodeBackground"); out = N_.new("ShaderNodeOutputWorld")
    bg.inputs["Color"].default_value = (0, 0, 0, 1); bg.inputs["Strength"].default_value = 0
    Lk.new(bg.outputs[0], out.inputs[0])

def add_bloom(scene):
    try:
        if hasattr(scene, "compositing_node_group"):
            ng = bpy.data.node_groups.get("DotBloom") or bpy.data.node_groups.new("DotBloom", 'CompositorNodeTree')
            ng.nodes.clear()
            if not len(ng.interface.items_tree):
                ng.interface.new_socket("Image", in_out='OUTPUT', socket_type='NodeSocketColor')
            scene.compositing_node_group = ng
            N_, Lk = ng.nodes, ng.links
            rl = N_.new("CompositorNodeRLayers"); gl = N_.new("CompositorNodeGlare"); out = N_.new("NodeGroupOutput")
            gl.inputs["Type"].default_value = 'Bloom'
            gl.inputs["Threshold"].default_value = 1.0; gl.inputs["Size"].default_value = 0.5; gl.inputs["Strength"].default_value = 0.45
            Lk.new(rl.outputs["Image"], gl.inputs["Image"]); Lk.new(gl.outputs["Image"], out.inputs[0])
        else:
            scene.use_nodes = True
            nt = scene.node_tree; N_, Lk = nt.nodes, nt.links
            for n in list(N_): N_.remove(n)
            rl = N_.new("CompositorNodeRLayers"); gl = N_.new("CompositorNodeGlare"); comp = N_.new("CompositorNodeComposite")
            gl.glare_type = 'BLOOM' if 'BLOOM' in [i.identifier for i in gl.bl_rna.properties['glare_type'].enum_items] else 'FOG_GLOW'
            gl.threshold = 0.8; gl.size = 7
            Lk.new(rl.outputs["Image"], gl.inputs[0]); Lk.new(gl.outputs[0], comp.inputs[0])
    except Exception as e:
        print("Bloom not set up:", e)

def setup_render(scene):
    r = scene.render
    r.resolution_x, r.resolution_y, r.resolution_percentage = 1080, 1920, RES_SCALE
    r.fps = FPS; scene.frame_start, scene.frame_end = 1, NF
    if ENGINE == "CYCLES":
        r.engine = 'CYCLES'; scene.cycles.samples = SAMPLES
    else:
        for eng in ('BLENDER_EEVEE', 'BLENDER_EEVEE_NEXT'):
            try: r.engine = eng; break
            except Exception: pass
        try: scene.eevee.taa_render_samples = SAMPLES
        except Exception: pass
    try: scene.view_settings.view_transform = 'Standard'
    except Exception: pass
    try: r.use_motion_blur = True; r.motion_blur_shutter = 0.5
    except Exception: pass
    try: r.filter_size = 2.2          # softer pixel filter: no grain, no shimmer
    except Exception: pass
    try: r.ffmpeg.constant_rate_factor = 'PERC_LOSSLESS'
    except Exception: pass
    try: pass
    except Exception: pass
    os.makedirs(OUTPUT, exist_ok=True)
    r.filepath = os.path.join(OUTPUT, "every_dot.mp4")
    ims = r.image_settings
    try: ims.media_type = 'VIDEO'
    except Exception: pass
    ims.file_format = 'FFMPEG'
    r.ffmpeg.format = 'MPEG4'; r.ffmpeg.codec = 'H264'
    r.ffmpeg.constant_rate_factor = 'PERC_LOSSLESS'; r.ffmpeg.ffmpeg_preset = 'GOOD'
    r.use_lock_interface = True


# ---------------- geometry nodes: the cloud ----------------
def cloud_group(Dn, Dc, mat):
    """Dn: x = visible count, y = collapse scale, z = cut plane;  Dc: x,y = direction to camera, z = time"""
    ng, N_, Lk, gi, go = new_gn("Measurements")
    dn = drv(N_, Lk, Dn); dc = drv(N_, Lk, Dc)
    idx = N_.new("GeometryNodeInputIndex"); pos = N_.new("GeometryNodeInputPosition")
    sp = N_.new("ShaderNodeSeparateXYZ"); Lk.new(pos.outputs[0], sp.inputs[0])
    side = M_(N_, Lk, 'ADD', M_(N_, Lk, 'MULTIPLY', sp.outputs[0], dc[0]), M_(N_, Lk, 'MULTIPLY', sp.outputs[1], dc[1]))
    gone = M_(N_, Lk, 'MAXIMUM', M_(N_, Lk, 'GREATER_THAN', idx.outputs[0], M_(N_, Lk, 'SUBTRACT', dn[0], 0.5)), M_(N_, Lk, 'GREATER_THAN', side, dn[2]))
    de = N_.new("GeometryNodeDeleteGeometry"); de.domain = 'POINT'
    Lk.new(gi.outputs[0], de.inputs["Geometry"]); Lk.new(gone, de.inputs["Selection"])
    # newest dots flash: age since this dot's birth (only the first 150 have a birth time)
    na = N_.new("GeometryNodeInputNamedAttribute"); na.data_type = 'FLOAT'; na.inputs["Name"].default_value = "birth"
    raw = M_(N_, Lk, 'SUBTRACT', dc[2], na.outputs["Attribute"])
    age = M_(N_, Lk, 'MAXIMUM', raw, 0.0)
    early = M_(N_, Lk, 'LESS_THAN', idx.outputs[0], 150.0)
    born = M_(N_, Lk, 'GREATER_THAN', raw, 0.0)
    flash = M_(N_, Lk, 'MULTIPLY', M_(N_, Lk, 'MULTIPLY', early, born), M_(N_, Lk, 'EXPONENT', M_(N_, Lk, 'MULTIPLY', age, -4.0)))
    st = N_.new("GeometryNodeStoreNamedAttribute"); st.data_type = 'FLOAT'; st.domain = 'POINT'; st.inputs["Name"].default_value = "flash"
    Lk.new(de.outputs[0], st.inputs["Geometry"]); Lk.new(flash, st.inputs["Value"])
    sc = N_.new("ShaderNodeVectorMath"); sc.operation = 'SCALE'; Lk.new(pos.outputs[0], sc.inputs[0]); Lk.new(dn[1], sc.inputs["Scale"])
    setp = N_.new("GeometryNodeSetPosition"); Lk.new(st.outputs[0], setp.inputs["Geometry"]); Lk.new(sc.outputs[0], setp.inputs["Position"])
    mp = N_.new("GeometryNodeMeshToPoints"); Lk.new(setp.outputs[0], mp.inputs["Mesh"])
    rad = M_(N_, Lk, 'MULTIPLY', POINT_PX * PXK * DIST / 2, M_(N_, Lk, 'ADD', 1.0, M_(N_, Lk, 'MULTIPLY', flash, 5.0)))
    rad = M_(N_, Lk, 'MULTIPLY', rad, M_(N_, Lk, 'ADD', 1.0, M_(N_, Lk, 'MULTIPLY', early, M_(N_, Lk, 'LESS_THAN', dn[0], 400.0))))
    Lk.new(rad, mp.inputs["Radius"])
    sm = N_.new("GeometryNodeSetMaterial"); sm.inputs["Material"].default_value = mat
    Lk.new(mp.outputs[0], sm.inputs["Geometry"]); Lk.new(sm.outputs[0], go.inputs[0])
    return ng

def cloud_mat():
    """each point is a small glossy sphere lit by real lights (volume + shadows); emission only for the newest-dot flash"""
    m = bpy.data.materials.new("Measurement"); m.use_nodes = True
    N_, Lk = m.node_tree.nodes, m.node_tree.links; N_.clear()
    out = N_.new("ShaderNodeOutputMaterial"); p = N_.new("ShaderNodeBsdfPrincipled")
    a1 = N_.new("ShaderNodeAttribute"); a1.attribute_type = 'GEOMETRY'; a1.attribute_name = "sgn"
    a2 = N_.new("ShaderNodeAttribute"); a2.attribute_type = 'GEOMETRY'; a2.attribute_name = "flash"
    mix = N_.new("ShaderNodeMix"); mix.data_type = 'RGBA'
    mix.inputs[6].default_value = (*BLUE, 1); mix.inputs[7].default_value = (*GOLD, 1)
    Lk.new(M_(N_, Lk, 'ADD', M_(N_, Lk, 'MULTIPLY', a1.outputs["Fac"], 0.5), 0.5), mix.inputs[0])
    a3 = N_.new("ShaderNodeAttribute"); a3.attribute_type = 'GEOMETRY'; a3.attribute_name = "rnd"
    shade = N_.new("ShaderNodeMix"); shade.data_type = 'RGBA'; shade.blend_type = 'MULTIPLY'; shade.inputs[0].default_value = 1.0
    Lk.new(mix.outputs[2], shade.inputs[6]); cr = N_.new("ShaderNodeCombineColor")
    for k in range(3): Lk.new(a3.outputs["Fac"], cr.inputs[k])
    Lk.new(cr.outputs[0], shade.inputs[7])
    Lk.new(shade.outputs[2], p.inputs["Base Color"])
    p.inputs["Roughness"].default_value = 0.4
    try: p.inputs["Specular IOR Level"].default_value = 0.35
    except Exception: pass
    val = N_.new("ShaderNodeValue"); val.outputs[0].default_value = 1.0
    stren = M_(N_, Lk, 'MULTIPLY', val.outputs[0], M_(N_, Lk, 'ADD', 1.0, M_(N_, Lk, 'MULTIPLY', a2.outputs["Fac"], 8.0)))
    try:
        Lk.new(mix.outputs[2], p.inputs["Emission Color"]); Lk.new(stren, p.inputs["Emission Strength"])
    except Exception: pass
    Lk.new(p.outputs[0], out.inputs[0])
    return m, val

def build_lights():
    import mathutils
    def light(name, kind, loc, energy, rgb, size=None, aim=(0, 0, 0)):
        ld = bpy.data.lights.new(name, kind); ld.energy = energy; ld.color = rgb
        try: ld.use_shadow = True
        except Exception: pass
        if size is not None:
            try: ld.size = size
            except Exception: pass
        ob_ = link(bpy.data.objects.new(name, ld)); ob_.location = loc
        ob_.rotation_euler = (mathutils.Vector(aim) - mathutils.Vector(loc)).to_track_quat('-Z', 'Y').to_euler()
    light("Key", 'SUN', (-60, -80, 120), 4.0, (1.0, 0.96, 0.9))
    try: bpy.data.lights["Key"].angle = math.radians(1.5)
    except Exception: pass
    light("Rim", 'SUN', (60, 120, 40), 2.2, (0.75, 0.85, 1.0))
    light("Fill", 'SUN', (90, -60, -40), 0.6, (1.0, 0.85, 0.7))

def view(t):
    phi = 0.35 * t + 0.6 * ef((t - 15.2) / 4.0)
    tilt = math.radians(14 + 22 * ef((t - T_TILT[0]) / (T_TILT[1] - T_TILT[0])) - 22 * ef((t - 23.5) / 2.5))
    return phi, tilt

# ---------------- build ----------------
def build():
    import mathutils
    scene = bpy.context.scene
    clear_scene()
    print(f"[1/4] Measuring the electron {NP:,} times...")
    xyz, sgn = sample(NP)
    me = bpy.data.meshes.new("Measurements"); me.vertices.add(NP); me.vertices.foreach_set("co", xyz.ravel())
    a = me.attributes.new("sgn", 'FLOAT', 'POINT'); a.data.foreach_set("value", sgn)
    birth = np.full(NP, 1e6, np.float32); i = np.arange(150)
    birth[:150] = T_B0 + np.log(i + 1) / math.log(150) * (T_B1 - T_B0)
    a = me.attributes.new("birth", 'FLOAT', 'POINT'); a.data.foreach_set("value", birth)
    rnd = np.random.default_rng(7).uniform(0.82, 1.12, NP).astype(np.float32)          # every particle a slightly different shade
    a = me.attributes.new("rnd", 'FLOAT', 'POINT'); a.data.foreach_set("value", rnd); me.update()

    print("[2/4] Camera...")
    C = np.zeros((NF, 3)); EUL = np.zeros((NF, 3)); RM = np.zeros((NF, 3, 3)); NDIR = np.zeros((NF, 2))
    for f in range(NF):
        phi, tilt = view(T[f])
        cam = np.array([math.sin(phi) * math.cos(tilt), -math.cos(phi) * math.cos(tilt), math.sin(tilt)]) * DIST
        fwd = -cam / np.linalg.norm(cam); right = np.cross(fwd, [0, 0, 1]); right /= np.linalg.norm(right); up = np.cross(right, fwd)
        R = np.stack([right, up, -fwd], 1); C[f] = cam; RM[f] = R
        EUL[f] = mathutils.Matrix(R.tolist()).to_euler('XYZ'); h = cam[:2] / np.linalg.norm(cam[:2]); NDIR[f] = h
    EUL = np.unwrap(EUL, axis=0)
    cd = bpy.data.cameras.new("Camera"); cd.lens = LENS; cd.sensor_fit = 'VERTICAL'; cd.sensor_height = 36
    cd.clip_start = 1.0; cd.clip_end = 1000; cd.shift_y = 40 / 1920 * 1.0
    try: cd.dof.use_dof = True; cd.dof.focus_distance = DIST; cd.dof.aperture_fstop = 2.8      # front/back particles soft, centre sharp
    except Exception: pass
    camo = link(bpy.data.objects.new("Camera", cd)); scene.camera = camo
    for j in range(3): bake(camo, "location", j, C[:, j]); bake(camo, "rotation_euler", j, EUL[:, j])

    print("[3/4] Cloud...")
    Dn = link(bpy.data.objects.new("Drive_count", None)); Dc = link(bpy.data.objects.new("Drive_cut", None))
    for o in (Dn, Dc): o.hide_render = True
    cnt = np.array([count(t) for t in T])
    col = np.array([1.0 - ef((t - T_COLLAPSE[0]) / (T_COLLAPSE[1] - T_COLLAPSE[0])) if t < T_B0 else 1.0 for t in T])
    cnt[(T >= T_COLLAPSE[1]) & (T < T_B0)] = 0.0
    cut = np.array([ef((t - T_CUT[0]) / (T_CUT[1] - T_CUT[0])) - ef((t - T_UNCUT[0]) / (T_UNCUT[1] - T_UNCUT[0])) for t in T])
    bake(Dn, "location", 0, cnt); bake(Dn, "location", 1, np.maximum(col, 1e-3)); bake(Dn, "location", 2, 200.0 * (1 - cut) - 0.5 * cut)
    bake(Dc, "location", 0, NDIR[:, 0]); bake(Dc, "location", 1, NDIR[:, 1]); bake(Dc, "location", 2, T)
    mat, val = cloud_mat()
    ob = link(bpy.data.objects.new("Atom", me)); ob.modifiers.new("cloud", 'NODES').node_group = cloud_group(Dn, Dc, mat)
    # brightness: each dot bright when there are few, softer when there are millions
    gain = BRIGHT * np.minimum(3.0, 0.015 * (2_000_000 / np.maximum(cnt, 1.0)) ** 0.62)   # glow of the dots (strong when few)
    bake(val.outputs[0], "default_value", None, gain, owner=mat.node_tree)
    # flash when the cloud collapses into the nucleus
    import bmesh
    fm = bpy.data.meshes.new("Flash"); b_ = bmesh.new(); bmesh.ops.create_uvsphere(b_, u_segments=24, v_segments=12, radius=1.0); b_.to_mesh(fm); b_.free()
    fmat, fval = glow_mat("FlashGlow", (1.0, 0.9, 0.75), 30.0); fm.materials.append(fmat)
    fl = link(bpy.data.objects.new("Flash", fm))
    fl_a = np.exp(-((T - T_COLLAPSE[1]) / 0.12) ** 2)
    for j in range(3): bake(fl, "scale", j, 0.5 + 2.5 * fl_a)
    bake(fval.outputs[0], "default_value", None, fl_a, owner=fmat.node_tree)

    print("[4/4] Text...")
    imgs, font = load_assets()
    def hud(ob_, cx, cy, depth=0.25):
        d = DIST * depth
        loc = np.array([C[f] + RM[f] @ np.array([(cx - 540) * PXK * d, (960 - cy) * PXK * d, -d]) for f in range(NF)])
        for j in range(3): bake(ob_, "location", j, loc[:, j]); bake(ob_, "rotation_euler", j, EUL[:, j]); ob_.scale[j] = PXK * d
    def pic(name, cx, cy, pairs):
        im = imgs[name]; w_, h_ = im.size
        me_ = bpy.data.meshes.new(name)
        me_.from_pydata([(-w_ / 2, -h_ / 2, 0), (w_ / 2, -h_ / 2, 0), (w_ / 2, h_ / 2, 0), (-w_ / 2, h_ / 2, 0)], [], [(0, 1, 2, 3)])
        uv_ = me_.uv_layers.new(); uv_.data.foreach_set("uv", [0, 0, 1, 0, 1, 1, 0, 1])
        o_ = link(bpy.data.objects.new(name, me_)); m_, v_ = image_mat(name, im); me_.materials.append(m_)
        hud(o_, cx, cy); bake(v_.outputs[0], "default_value", None, fade(pairs), owner=m_.node_tree)
    pic("hook", 540, 260, [(0, 1), (2.3, 1), (2.7, 0), (SECONDS, 0)])
    pic("top1", 540, 230, show(2.9, 8.3)); pic("top2", 540, 230, show(8.7, 11.6, 0.4)); pic("top3", 540, 230, show(12.0, 15.2, 0.4))
    pic("top4", 540, 230, show(15.6, 20.2)); pic("top5", 540, 200, show(20.6, 25.8, 0.4))
    pic("form", 540, 1690, show(16.2, 20.3, 0.6)); pic("node", 540, 1690, show(22.6, 25.8))
    pic("end", 540, 1680, [(0, 0), (T_END, 0), (T_END + 0.7, 1), (SECONDS, 1)])
    cshow = show(2.9, 15.8); pic("cnt_l", 540, 1730, cshow); pic("handle", 540, 1872, [(0, 1), (SECONDS, 1)])
    Dv = link(bpy.data.objects.new("Drive_counter", None)); Dv.hide_render = True
    shown = np.floor(np.minimum(cnt, NP)); shown[T < T_B0] = 0
    bake(Dv, "location", 0, shown - 0.49)
    cm, cv = glow_mat("CounterMat", (1, 1, 1), 1.0)
    co = link(bpy.data.objects.new("Counter", bpy.data.meshes.new("CounterMesh")))
    co.modifiers.new("cnt", 'NODES').node_group = counter_group(Dv, 0, font, cm)
    hud(co, 540, 1680); bake(cv.outputs[0], "default_value", None, fade(cshow), owner=cm.node_tree)

    build_world(); build_lights(); setup_render(scene); add_bloom(scene)
    for scr in bpy.data.screens:
        for area in scr.areas:
            if area.type == 'VIEW_3D':
                for sp_ in area.spaces:
                    if sp_.type == 'VIEW_3D':
                        try: sp_.shading.use_compositor = 'DISABLED'
                        except Exception: pass
    scene.frame_set(1)
    print(f"Ready: {NF} frames, {NP:,} measurements. Ctrl+F12 -> {scene.render.filepath}")

def _deferred():
    try: build()
    except Exception:
        import traceback; traceback.print_exc()
    return None

if bpy.app.background:
    build()
else:
    print("Building... (Window > Toggle System Console to watch)")
    bpy.app.timers.register(_deferred, first_interval=0.2)
